	// named cookies.  So we use the php globals that webrequest delegates to.
	if ( count( $_COOKIE ) > 0 ) {
		return false;
	}
	// Log the presence of cookies for debugging purposes
	$requestLogger = LoggerFactory::getInstance()->getLogger( 'request' );
